"""Real Postgres, no mocking -- same TEST_DATABASE_URL setup as
test_checker.py. Uses FastAPI's TestClient, which manages its own event
loop, so this is a plain TestCase (not IsolatedAsyncioTestCase) with
asyncio.run() for the async DB setup/teardown.
"""
import asyncio
import os
import unittest

import asyncpg
from fastapi.testclient import TestClient

from app import cache, db
from app.main import app

TEST_DATABASE_URL = os.environ.get(
    "TEST_DATABASE_URL",
    "postgresql://repo_access:repo_access@localhost:5432/repo_access_test",
)


class TestRoutes(unittest.TestCase):
    def setUp(self):
        asyncio.run(self._async_setup())
