.app {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

.app h1 {
  font-size: 1.75rem;
  margin: 0 0 1.5rem;
}

.panels {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

section {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.25rem;
}

section h2 {
  font-size: 1.1rem;
  margin: 0 0 1rem;
}

section h3 {
  font-size: 0.95rem;
  margin: 1.25rem 0 0.5rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.field-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: flex-end;
  margin-bottom: 1rem;
}

.field-row label {
  display: flex;
  flex-direction: column;
  font-size: 0.8rem;
  color: var(--text-muted);
  gap: 0.3rem;
}

input,
select {
  font: inherit;
  color: var(--text);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 0.5rem 0.6rem;
}

input:focus,
select:focus,
button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

button {
  font: inherit;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 6px;
  padding: 0.55rem 1.1rem;
  cursor: pointer;
}

button:disabled {
  opacity: 0.5;
  cursor: default;
}

button.link {
  color: var(--accent);
  background: none;
  font-weight: 500;
  text-decoration: underline;
  padding: 0;
  border-radius: 0;
}

.result {
  padding: 0.9rem 1rem;
  border-radius: 8px;
  margin-bottom: 1rem;
}

.result.allowed {
  background: var(--allow-bg);
  color: var(--allow-text);
}

.result.denied {
  background: var(--deny-bg);
  color: var(--deny-text);
}

.result strong {
  display: block;
  margin-bottom: 0.25rem;
}

.staleness-note {
  font-size: 0.8rem;
  opacity: 0.85;
  margin: 0.4rem 0 0;
}

.explain .chain {
  font-family: ui-monospace, Consolas, monospace;
  font-size: 0.9rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 0.6rem 0.75rem;
}

.explain .reason {
  color: var(--deny-text);
  font-size: 0.85rem;
}

.error {
  color: var(--deny-text);
}

.repo-list {
  list-style: none;
  padding: 0;
  margin: 0 0 1rem;
}

.repo-list li {
  padding: 0.3rem 0;
  border-bottom: 1px solid var(--border);
}

.repo-list li:last-child {
  border-bottom: none;
}

@media (max-width: 700px) {
  .panels {
    grid-template-columns: 1fr;
  }
}
